const visual = {
  prepare: function (input) {
    var labels = [];
    for (var i = -5; i <= 5; i++) {
      labels.push({ kind: 'text', payload: String(i) });
    }
    return labels;
  },
  render: function (input, metrics) {
    var width = input.viewport.widthDu;
    var height = input.viewport.heightDu;
    var x0 = width * 0.08;
    var x1 = width * 0.92;
    var y = height * 0.55;
    var tick = Math.min(9, height * 0.04);
    var step = (x1 - x0) / 10;
    var axisCommands = [['M', x0, y], ['L', x1, y]];
    var tickCommands = [];
    var children = [];
    var labelY = y + tick + 10;
    for (var i = 0; i < 11; i++) {
      var x = x0 + step * i;
      tickCommands.push(['M', x, y - tick], ['L', x, y + tick]);
      children.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: x, y: labelY },
        hAlign: 'center',
        vAlign: 'top',
        color: '#26354a'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'number-line-range-minus5-to-5',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: width, height: height },
      paths: [
        { id: 'axis', commands: axisCommands },
        { id: 'ticks', commands: tickCommands }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'ticks', fill: '#26354a', stroke: { width: 2, cap: 'round' } }
        ].concat(children)
      }
    };
  }
};
